function httpsUrl(value, label) {
  if (
    typeof value !== "string" ||
    !/^https:\/\/[a-z0-9.-]+(?::\d+)?(?:[/?][^\s]*)?$/i.test(value)
  ) {
    throw new Error(label + " must be an HTTPS URL without embedded credentials");
  }
  return value.replace(/^https:/i, "https:");
}
export default function configure({ html, pdfUrl }) {
  if (!html.trim()) throw new Error("Enter HTML to render");
  return { html, pdf: { url: httpsUrl(pdfUrl, "Source PDF"), async: false } };
}

