function httpsUrl(value, label) {
  if (
    typeof value !== "string" ||
    !/^https:\/\/[a-z0-9.-]+(?::\d+)?(?:[/?][^\s]*)?$/i.test(value)
  ) {
    throw new Error(label + " must be an HTTPS URL without embedded credentials");
  }
  return value.replace(/^https:/i, "https:");
}

function uploadLinks(body) {
  if (body?.error !== false) throw new Error("PDF.co did not provide temporary upload links");
  return {
    putUrl: httpsUrl(body.presignedUrl, "PDF upload"),
    pdfUrl: httpsUrl(body.url, "Temporary PDF download"),
  };
}

function requirePdf(bytes) {
  if (bytes.length < 8 || String.fromCharCode(...bytes.subarray(0, 5)) !== "%PDF-") {
    throw new Error("The HTML rendering response is not a PDF");
  }
}
export default async function verify({ pdf, links }, context) {
  requirePdf(await context.artifact.open(pdf));
  const { putUrl, pdfUrl } = uploadLinks(links);
  return { putUrl, pdf: { url: pdfUrl, async: false } };
}

