function pageCount(value, source) {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new Error("PDF.co did not report a valid page count for " + source);
  }
  return value;
}
export default function prepare({ pdf, info }) {
  if (info?.error !== false) throw new Error("PDF.co could not inspect " + "the HTML-rendered PDF");
  const count = pageCount(info.info?.PageCount, "the HTML-rendered PDF");
  return { count, body: { ...pdf, pages: count === 1 ? "0" : "0-" + (count - 1) } };
}

