function httpsUrl(value, label) {
  if (
    typeof value !== "string" ||
    !/^https:\/\/[a-z0-9.-]+(?::\d+)?(?:[/?][^\s]*)?$/i.test(value)
  ) {
    throw new Error(label + " must be an HTTPS URL without embedded credentials");
  }
  return value.replace(/^https:/i, "https:");
}

function listPages(body, count, source) {
  if (body?.error !== false || !Array.isArray(body.urls)) {
    throw new Error("PDF.co did not return PNG pages for " + source);
  }
  if (body.urls.length !== count || new Set(body.urls).size !== count) {
    throw new Error("PDF.co returned an incomplete or duplicate page list for " + source);
  }
  return body.urls.map((url, index) => ({
    source,
    page: index + 1,
    pageCount: count,
    url: httpsUrl(url, "PNG download"),
  }));
}
export default function plan({ htmlPng, urlPng, htmlCount, urlCount }) {
  return {
    plan: [...listPages(htmlPng, htmlCount, "html"), ...listPages(urlPng, urlCount, "pdf-url")],
  };
}

