function requirePng(bytes, page) {
  const signature = [137, 80, 78, 71, 13, 10, 26, 10];
  if (
    bytes.length <= signature.length ||
    !signature.every((byte, index) => bytes[index] === byte)
  ) {
    throw new Error(page.source + " page " + page.page + " did not download as PNG");
  }
}

export default async function nextPage({ plan, state, downloaded }, context) {
  const pages = state?.pages ?? [];
  if (state && downloaded) {
    const current = plan[pages.length];
    requirePng(await context.artifact.open(downloaded), current);
    pages.push({
      source: current.source,
      page: current.page,
      pageCount: current.pageCount,
      png: downloaded,
    });
  }
  const next = plan[pages.length];
  return { more: next !== undefined, url: next?.url ?? plan.at(-1).url, state: { pages }, pages };
}
